const webhook = $("HubSpot Closed Conversation Webhook").item.json.body || {};
const contactSearch = $("Find Contact").item.json || {};
const messageResponse = $("Get Thread Messages").item.json || {};

const contact = contactSearch.results?.[0] || {};
const contactProps = contact.properties || {};
const messages = messageResponse.results || [];

function clean(value) {
  return value === undefined || value === null ? "" : String(value).trim();
}

function stripHtml(value) {
  return clean(value)
    .replace(/<[^>]+>/g, " ")
    .replace(/&nbsp;/g, " ")
    .replace(/&amp;/g, "&")
    .replace(/&lt;/g, "<")
    .replace(/&gt;/g, ">")
    .replace(/\s+/g, " ")
    .trim();
}

function extractText(message) {
  return (
    message.text ||
    message.richText ||
    message.body ||
    message.content ||
    message.message ||
    message.plainText ||
    message.previewText ||
    ""
  );
}

function extractSender(message) {
  const actorId =
    message.senders?.[0]?.actorId ||
    message.sender?.actorId ||
    message.createdBy ||
    "";

  if (actorId.startsWith("V-")) return "Visitor";
  if (actorId.startsWith("A-")) return "Atlas HXM assistant";
  if (actorId.startsWith("S-")) return "Atlas HXM assistant";

  if (message.sender?.name) return message.sender.name;
  if (message.senders?.[0]?.name) return message.senders[0].name;
  if (message.direction === "INCOMING") return "Visitor";
  if (message.direction === "OUTGOING") return "Atlas HXM assistant";

  return "Unknown";
}

function isVisitorMessage(message) {
  const actorId =
    message.senders?.[0]?.actorId ||
    message.sender?.actorId ||
    "";

  return (
    actorId.startsWith("V-") ||
    message.direction === "INCOMING" ||
    extractSender(message) === "Visitor"
  );
}

function extractEmail(text) {
  const match = clean(text).match(/[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}/i);
  return match ? match[0].toLowerCase() : "";
}

function extractPhone(text) {
  const matches = clean(text).match(/(?:\+?\d[\d\s().-]{7,}\d)/g) || [];

  const cleaned = matches
    .map((phone) => phone.replace(/\s+/g, " ").trim())
    .filter((phone) => {
      const digitCount = phone.replace(/\D/g, "").length;
      return digitCount >= 8 && digitCount <= 16;
    });

  return cleaned[0] || "";
}

function extractDomainFromEmail(email) {
  const domain = clean(email).toLowerCase().split("@")[1] || "";

  const personalDomains = new Set([
    "gmail.com",
    "yahoo.com",
    "hotmail.com",
    "outlook.com",
    "icloud.com",
    "aol.com",
    "proton.me",
    "protonmail.com",
    "live.com",
    "msn.com"
  ]);

  return domain && !personalDomains.has(domain) ? domain : "";
}

function extractDomainFromText(text) {
  const matches = clean(text).match(
    /(?:https?:\/\/)?(?:www\.)?([a-z0-9-]+\.[a-z]{2,})(?:\/[^\s]*)?/gi
  ) || [];

  const excluded = new Set([
    "hubspot.com",
    "meetings.hubspot.com",
    "atlashxm.com",
    "www.atlashxm.com"
  ]);

  for (const raw of matches) {
    const normalized = raw
      .replace(/^https?:\/\//i, "")
      .replace(/^www\./i, "")
      .split("/")[0]
      .toLowerCase();

    if (normalized && !excluded.has(normalized)) return normalized;
  }

  return "";
}

function guessCompanyFromDomain(domain) {
  const root = clean(domain)
    .replace(/^www\./, "")
    .split(".")[0]
    .replace(/[-_]+/g, " ")
    .trim();

  if (!root) return "";

  return root
    .split(" ")
    .map((word) => word ? word[0].toUpperCase() + word.slice(1) : "")
    .join(" ");
}

function extractCompanyName(text, domain) {
  const cleaned = clean(text);

  const patterns = [
    /(?:company name|company|organization|business|employer)\s*(?:is|:|-)\s*([A-Z0-9&.,'’\- ]{2,80})/i,
    /(?:I work for|I'm with|I am with|we are with|we're with|we are from|we're from|from)\s+([A-Z0-9&.,'’\- ]{2,80})/i
  ];

  for (const pattern of patterns) {
    const match = cleaned.match(pattern);
    if (match?.[1]) {
      return match[1]
        .replace(/\s+(and|but|we|I|looking|need|want|are)\b.*$/i, "")
        .replace(/[.。]+$/, "")
        .trim();
    }
  }

  return guessCompanyFromDomain(domain);
}

const sortedMessages = [...messages].sort((a, b) => {
  return new Date(a.createdAt || 0) - new Date(b.createdAt || 0);
});

const transcript = sortedMessages
  .map((message) => {
    const timestamp = clean(message.createdAt || message.updatedAt || message.sentAt);
    const sender = clean(extractSender(message));
    const text = stripHtml(extractText(message));

    if (!text) return null;
    return `[${timestamp}] ${sender}: ${text}`;
  })
  .filter(Boolean)
  .join("\n\n");

const visitorMessages = sortedMessages
  .filter(isVisitorMessage)
  .map((message) => stripHtml(extractText(message)))
  .filter(Boolean);

const visitorText = visitorMessages.join("\n");

const existingEmail = clean(contactProps.email);
const extractedEmail = extractEmail(visitorText);
const email = existingEmail || extractedEmail;

const existingPhone = clean(contactProps.phone || contactProps.mobilephone);
const extractedPhone = extractPhone(visitorText);
const phone = existingPhone || extractedPhone;

const existingDomain = clean(contactProps.domain || contactProps.website);
const extractedDomain = extractDomainFromText(visitorText) || extractDomainFromEmail(email);
const companyDomain = existingDomain || extractedDomain;

const existingCompany = clean(contactProps.company);
const extractedCompany = extractCompanyName(visitorText, companyDomain);
const companyName = existingCompany || extractedCompany;

const threadId = clean(webhook.hs_thread_id);
const contactId = clean(webhook.hs_object_id || contact.id || contactProps.hs_object_id);

const messageDates = sortedMessages
  .map((message) => clean(message.createdAt || message.updatedAt || message.sentAt))
  .filter(Boolean);

const lastMessageDate = messageDates.length
  ? messageDates[messageDates.length - 1]
  : new Date().toISOString();

return [
  {
    json: {
      contactId,
      hs_object_id: contactId,
      threadId,
      hs_thread_id: threadId,

      email,
      firstname: clean(contactProps.firstname),
      lastname: clean(contactProps.lastname),
      phone,
      company: companyName,
      company_domain: companyDomain,
      domain: companyDomain,
      website: companyDomain ? `https://${companyDomain.replace(/^https?:\/\//, "")}` : "",
      jobtitle: clean(contactProps.jobtitle),

      existing_lifecyclestage: clean(contactProps.lifecyclestage),
      existing_hs_lead_status: clean(contactProps.hs_lead_status),

      existingContact: contact,
      contactProperties: contactProps,

      rawMessages: sortedMessages,
      visitorMessages,
      transcript,

      chatbot_transcript: transcript,
      chatbot_session_id: threadId,
      chatbot_last_session_date: lastMessageDate,
      ai_chatbot_processed: "Yes"
    }
  }
];

const context = $("Normalize Conversation + Transcript").item.json || {};

let analysis = $json.output || $json;

if (typeof analysis === "string") {
  let raw = analysis
    .trim()
    .replace(/^```json\s*/i, "")
    .replace(/^```\s*/i, "")
    .replace(/```$/i, "")
    .trim();

  try {
    analysis = JSON.parse(raw);
  } catch (error) {
    analysis = {};
  }
}

function clean(value) {
  return value === undefined || value === null ? "" : String(value).trim();
}

function truncate(value, limit = 65000) {
  const text = clean(value);
  return text.length > limit ? text.slice(0, limit - 3) + "..." : text;
}

function joinArray(value) {
  if (!Array.isArray(value)) return clean(value);
  return value.map(clean).filter(Boolean).join("; ");
}

function firstValue(...values) {
  for (const value of values) {
    const cleaned = clean(value);
    if (cleaned) return cleaned;
  }
  return "";
}

const chatbotCountries = Array.isArray(analysis.chatbot_countries)
  ? analysis.chatbot_countries
  : Array.isArray(analysis.countries)
    ? analysis.countries
    : [];

const mqlStatus = firstValue(
  analysis.chatbot_mql_status,
  analysis.mql_classification,
  "Non-MQL"
);

const isMQL = clean(mqlStatus).toLowerCase() === "mql";

const lastSessionDate = firstValue(
  analysis.chatbot_last_session_date,
  context.chatbot_last_session_date,
  new Date().toISOString()
);

const followUpBody = firstValue(
  analysis.follow_up_email_body,
  analysis.ai_mql_response_1
);

const fields = {
  // Identifier fields
  contactId: context.contactId,
  hs_object_id: context.contactId,

  // Standard contact fields
  email: firstValue(context.email),
  firstname: firstValue(context.firstname, analysis.first_name),
  lastname: firstValue(context.lastname, analysis.last_name),
  phone: firstValue(context.phone, analysis.phone),
  jobtitle: firstValue(context.jobtitle, analysis.job_title),
  company: firstValue(context.company, analysis.company),
  domain: firstValue(context.domain, context.company_domain, analysis.company_domain),
  website: firstValue(context.website),

  // Chatbot fields
  chatbot_transcript: truncate(firstValue(
    analysis.chatbot_transcript,
    context.chatbot_transcript,
    context.transcript
  ), 64000),

  chatbot_wses: truncate(firstValue(
    analysis.chatbot_wses,
    analysis.workforce_setup
  ), 1000),

  chatbot_timeline: truncate(firstValue(
    analysis.chatbot_timeline,
    analysis.timeline,
    "No timeline provided"
  ), 1000),

  chatbot_countries: truncate(joinArray(chatbotCountries), 1000),

  chatbot_eor_intent: firstValue(
    analysis.chatbot_eor_intent,
    analysis.entity_intent,
    "unknown"
  ),

  chatbot_mql_status: mqlStatus,

  chatbot_session_id: firstValue(
    analysis.chatbot_session_id,
    context.chatbot_session_id,
    context.threadId
  ),

  chatbot_buyer_need: truncate(firstValue(
    analysis.chatbot_buyer_need,
    analysis.buyer_need,
    "Unclear - no specific buyer need was identified."
  ), 4000),

  chatbot_pain_points: truncate(firstValue(
    analysis.chatbot_pain_points
  ), 4000),

  ai_chatbot_processed: "Yes",

  chatbot_questions_asked: truncate(firstValue(
    analysis.chatbot_questions_asked
  ), 4000),

  chatbot_last_session_date: lastSessionDate,

  chatbot_recommended_next_step: truncate(firstValue(
    analysis.chatbot_recommended_next_step,
    analysis.recommended_next_step
  ), 4000),

  chatbot_disqualification_reason: truncate(firstValue(
    analysis.chatbot_disqualification_reason,
    analysis.disqualification_reason
  ), 4000),

  // AI email body property
  ai_mql_response_1: truncate(followUpBody, 64000),

  // Optional supporting fields
  maia_chat_summary: truncate(firstValue(analysis.summary), 64000),
  chatbot_intent_category: firstValue(analysis.intent_category, "unknown"),
  chatbot_lead_temperature: firstValue(analysis.lead_temperature, "unknown"),
  chatbot_hiring_count: firstValue(analysis.hiring_count),
  chatbot_hiring_timeline: firstValue(analysis.timeline),
  customer_agent_conversation_id: firstValue(context.threadId),
  chatbot_session_ended: "true",
  chatbot_session_ended_at: lastSessionDate
};

if (isMQL) {
  fields.lifecyclestage = "marketingqualifiedlead";
  fields.hs_lead_status = "NEW";
  fields.customer_agent_mql_date = new Date().toISOString().slice(0, 10);
}

// Prevent blank values from overwriting existing HubSpot values.
for (const key of Object.keys(fields)) {
  if (fields[key] === "") {
    delete fields[key];
  }
}

return [
  {
    json: {
      ...fields,
      analysis,
      isMQL,
      threadId: context.threadId,
      contactId: context.contactId
    }
  }
];
